BEGIN;
CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE EXTENSION IF NOT EXISTS "uuid-ossp";
CREATE TYPE public.tc_account_status AS ENUM ('pending','active','restricted','suspended','inactive');
CREATE TYPE public.tc_conflict_reason AS ENUM ('version_mismatch','invalid_state_transition','custody_mismatch','duplicate_operation','stale_event','route_mismatch','unauthorized_actor','evidence_incomplete');
CREATE OR REPLACE FUNCTION public.tc_generate_public_id(p_prefix text) RETURNS text LANGUAGE sql VOLATILE SET search_path = public, pg_temp AS $$ SELECT upper(p_prefix) || '-' || upper(substr(replace(gen_random_uuid()::text, '-', ''), 1, 16)); $$;
REVOKE ALL ON FUNCTION public.tc_generate_public_id(text) FROM PUBLIC;
CREATE OR REPLACE FUNCTION public.tc_set_updated_at() RETURNS trigger LANGUAGE plpgsql SET search_path = public, pg_temp AS $$ BEGIN NEW.updated_at := now(); RETURN NEW; END; $$;
REVOKE ALL ON FUNCTION public.tc_set_updated_at() FROM PUBLIC;
CREATE TABLE public.persons (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), public_id text UNIQUE NOT NULL DEFAULT public.tc_generate_public_id('PER') CHECK (public_id LIKE 'PER-%'), auth_user_id uuid UNIQUE NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, full_name text, email text, phone text, preferred_language text NOT NULL DEFAULT 'es', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE public.users (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, person_id uuid UNIQUE NOT NULL REFERENCES public.persons(id) ON DELETE CASCADE, display_name text, photo_url text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE public.profiles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), public_id text UNIQUE NOT NULL, person_id uuid NOT NULL REFERENCES public.persons(id) ON DELETE CASCADE, profile_type text NOT NULL CHECK (profile_type IN ('CLI','CON','RSG','VEN','TIE','PAS','PTC','EMP','SOP','ADM')), status public.tc_account_status NOT NULL DEFAULT 'pending', territory_id text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT chk_profile_public_id_prefix CHECK ((profile_type='CLI' AND public_id LIKE 'CLI-%') OR (profile_type='CON' AND public_id LIKE 'CON-%') OR (profile_type='RSG' AND public_id LIKE 'RSG-%') OR (profile_type='VEN' AND public_id LIKE 'VEN-%') OR (profile_type='TIE' AND public_id LIKE 'TIE-%') OR (profile_type='PAS' AND public_id LIKE 'PAS-%') OR (profile_type='PTC' AND public_id LIKE 'PTC-%') OR (profile_type='EMP' AND public_id LIKE 'EMP-%') OR (profile_type='SOP' AND public_id LIKE 'SOP-%') OR (profile_type='ADM' AND public_id LIKE 'ADM-%')));
CREATE TABLE public.store_directory (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), store_profile_id uuid UNIQUE NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, store_public_id text UNIQUE NOT NULL CHECK (store_public_id LIKE 'TIE-%' OR store_public_id LIKE 'VEN-%'), commercial_name text NOT NULL, territory_id text, community_label text, is_open boolean NOT NULL DEFAULT true, is_active boolean NOT NULL DEFAULT true, rating numeric(3,2) CHECK (rating IS NULL OR (rating>=0 AND rating<=5)), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE public.orders (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), public_id text UNIQUE NOT NULL DEFAULT public.tc_generate_public_id('ORD') CHECK (public_id LIKE 'ORD-%'), client_profile_id uuid NOT NULL REFERENCES public.profiles(id), total_minor bigint NOT NULL CHECK (total_minor>=0), currency varchar(3) NOT NULL DEFAULT 'GTQ', destination_type text NOT NULL, destination_id text, idempotency_key text UNIQUE NOT NULL, state text NOT NULL DEFAULT 'CREATED', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE public.sub_orders (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), public_id text UNIQUE NOT NULL DEFAULT public.tc_generate_public_id('SUB') CHECK (public_id LIKE 'SUB-%'), order_id uuid NOT NULL REFERENCES public.orders(id) ON DELETE CASCADE, store_profile_id uuid NOT NULL REFERENCES public.profiles(id), subtotal_minor bigint NOT NULL CHECK (subtotal_minor>=0), state text NOT NULL DEFAULT 'CREATED', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE public.packages (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), public_id text UNIQUE NOT NULL DEFAULT public.tc_generate_public_id('PKG') CHECK (public_id LIKE 'PKG-%'), sub_order_id uuid NOT NULL REFERENCES public.sub_orders(id) ON DELETE CASCADE, current_custodian_id uuid NOT NULL REFERENCES public.profiles(id), state text NOT NULL DEFAULT 'CREATED', version bigint NOT NULL DEFAULT 0 CHECK (version>=0), weight_kg numeric(10,3) NOT NULL DEFAULT 0 CHECK (weight_kg>=0), volume_m3 numeric(10,4) NOT NULL DEFAULT 0 CHECK (volume_m3>=0), requires_cold_chain boolean NOT NULL DEFAULT false, requires_fragile_handling boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE public.vehicles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), public_id text UNIQUE NOT NULL DEFAULT public.tc_generate_public_id('VEH') CHECK (public_id LIKE 'VEH-%'), owner_profile_id uuid NOT NULL REFERENCES public.profiles(id), plate_number text NOT NULL, transport_type text, max_weight_kg numeric(10,3) NOT NULL CHECK (max_weight_kg>=0), max_volume_m3 numeric(10,4) NOT NULL CHECK (max_volume_m3>=0), max_packages integer CHECK (max_packages IS NULL OR max_packages>=0), supports_cold_chain boolean NOT NULL DEFAULT false, supports_fragile boolean NOT NULL DEFAULT false, supports_bulky boolean NOT NULL DEFAULT false, supports_rural_cargo boolean NOT NULL DEFAULT false, is_active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE public.driver_vehicle_authorizations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), driver_profile_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, vehicle_id uuid NOT NULL REFERENCES public.vehicles(id) ON DELETE CASCADE, authorization_type text NOT NULL, valid_from timestamptz NOT NULL, valid_until timestamptz, is_active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), CHECK (valid_until IS NULL OR valid_until>=valid_from), UNIQUE(driver_profile_id,vehicle_id));
CREATE TABLE public.route_opportunities (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), public_id text UNIQUE NOT NULL DEFAULT public.tc_generate_public_id('RTE') CHECK (public_id LIKE 'RTE-%'), territory_id text NOT NULL, required_role text NOT NULL, total_weight_kg numeric(10,3) NOT NULL CHECK (total_weight_kg>=0), total_volume_m3 numeric(10,4) NOT NULL CHECK (total_volume_m3>=0), package_count integer NOT NULL CHECK (package_count>0), requires_cold_chain boolean NOT NULL DEFAULT false, requires_fragile_handling boolean NOT NULL DEFAULT false, state text NOT NULL DEFAULT 'OPEN', version bigint NOT NULL DEFAULT 0 CHECK (version>=0), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE public.route_assignments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), public_id text UNIQUE NOT NULL DEFAULT public.tc_generate_public_id('ASG') CHECK (public_id LIKE 'ASG-%'), route_id uuid NOT NULL REFERENCES public.route_opportunities(id), driver_profile_id uuid NOT NULL REFERENCES public.profiles(id), vehicle_id uuid NOT NULL REFERENCES public.vehicles(id), state text NOT NULL DEFAULT 'ASSIGNED', version bigint NOT NULL DEFAULT 0 CHECK (version>=0), assigned_at timestamptz NOT NULL DEFAULT now(), released_at timestamptz, idempotency_key text UNIQUE NOT NULL, updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE public.movements (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), public_id text UNIQUE NOT NULL DEFAULT public.tc_generate_public_id('MOV') CHECK (public_id LIKE 'MOV-%'), route_id uuid REFERENCES public.route_opportunities(id), route_assignment_id uuid REFERENCES public.route_assignments(id), from_profile_id uuid REFERENCES public.profiles(id), to_profile_id uuid REFERENCES public.profiles(id), movement_type text NOT NULL CHECK (movement_type IN ('STORE_TO_PTC','PTC_TO_PTC','PTC_TO_DRIVER','DRIVER_TO_PTC','PTC_TO_DELIVERY','DELIVERY_TO_CUSTOMER','RETURN')), state text NOT NULL DEFAULT 'PLANNED' CHECK (state IN ('PLANNED','ASSIGNED','READY','IN_TRANSIT','ARRIVED','TRANSFER_PENDING','COMPLETED','FAILED','CANCELLED')), sequence_number integer NOT NULL DEFAULT 1 CHECK(sequence_number>0), expected_from_at timestamptz, expected_to_at timestamptz, departed_at timestamptz, arrived_at timestamptz, completed_at timestamptz, version bigint NOT NULL DEFAULT 0 CHECK(version>=0), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CHECK(expected_from_at IS NULL OR expected_to_at IS NULL OR expected_to_at>=expected_from_at));
CREATE TABLE public.movement_packages (movement_id uuid NOT NULL REFERENCES public.movements(id) ON DELETE CASCADE, package_id uuid NOT NULL REFERENCES public.packages(id) ON DELETE CASCADE, added_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(movement_id,package_id));
CREATE TABLE public.idempotency_records (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), operation_type text NOT NULL, idempotency_key text NOT NULL, person_id uuid NOT NULL REFERENCES public.persons(id), request_hash text NOT NULL, response_payload jsonb, status text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), completed_at timestamptz, UNIQUE(operation_type,idempotency_key));
CREATE TABLE public.event_inbox (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), event_id text UNIQUE NOT NULL CHECK(event_id LIKE 'EVT-%'), idempotency_key text UNIQUE NOT NULL, request_hash text NOT NULL, event_type text NOT NULL, auth_user_id uuid NOT NULL REFERENCES auth.users(id), person_id uuid NOT NULL REFERENCES public.persons(id), profile_id uuid NOT NULL REFERENCES public.profiles(id), package_id uuid REFERENCES public.packages(id), movement_id uuid REFERENCES public.movements(id), route_id uuid REFERENCES public.route_opportunities(id), expected_version bigint, occurred_at timestamptz NOT NULL, received_at timestamptz NOT NULL DEFAULT now(), payload jsonb NOT NULL DEFAULT '{}'::jsonb, processing_status text NOT NULL DEFAULT 'PENDING', disposition text, resulting_state text, resulting_version bigint, conflict_id text, error_code text, processed_at timestamptz);
CREATE TABLE public.custody_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), public_id text UNIQUE NOT NULL DEFAULT public.tc_generate_public_id('CST') CHECK(public_id LIKE 'CST-%'), package_id uuid NOT NULL REFERENCES public.packages(id), movement_id uuid REFERENCES public.movements(id), from_profile_id uuid REFERENCES public.profiles(id), to_profile_id uuid REFERENCES public.profiles(id), event_id text NOT NULL REFERENCES public.event_inbox(event_id), occurred_at timestamptz NOT NULL, recorded_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE public.sync_conflicts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), public_id text UNIQUE NOT NULL DEFAULT public.tc_generate_public_id('CNF') CHECK(public_id LIKE 'CNF-%'), event_id text NOT NULL REFERENCES public.event_inbox(event_id), entity_id text NOT NULL, current_version bigint NOT NULL, expected_version bigint, current_state text NOT NULL, requested_event text NOT NULL, reason public.tc_conflict_reason NOT NULL, detected_at timestamptz NOT NULL DEFAULT now(), resolution_status text NOT NULL DEFAULT 'PENDING' CHECK(resolution_status IN ('PENDING','RESOLVED','DISCARDED')), resolved_by uuid REFERENCES public.persons(id), resolved_at timestamptz, resolution_note text);
ALTER TABLE public.event_inbox ADD CONSTRAINT fk_event_inbox_conflict FOREIGN KEY(conflict_id) REFERENCES public.sync_conflicts(public_id);
CREATE TABLE public.evidence (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), public_id text UNIQUE NOT NULL DEFAULT public.tc_generate_public_id('EVD') CHECK(public_id LIKE 'EVD-%'), uploader_profile_id uuid NOT NULL REFERENCES public.profiles(id), package_id uuid REFERENCES public.packages(id), movement_id uuid REFERENCES public.movements(id), route_id uuid REFERENCES public.route_opportunities(id), source_event_id text REFERENCES public.event_inbox(event_id), evidence_type text NOT NULL, bucket_id text NOT NULL DEFAULT 'tc-evidence', object_path text UNIQUE NOT NULL, mime_type text NOT NULL, size_bytes bigint NOT NULL CHECK(size_bytes>=0), sha256 text NOT NULL, captured_at timestamptz NOT NULL, uploaded_at timestamptz NOT NULL DEFAULT now(), status text NOT NULL DEFAULT 'UPLOADED' CHECK(status IN ('UPLOADED','VERIFIED','REJECTED','RETAINED','DELETED')), retention_until timestamptz);
CREATE TABLE public.audit_logs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), public_id text UNIQUE NOT NULL DEFAULT public.tc_generate_public_id('AUD') CHECK(public_id LIKE 'AUD-%'), actor_person_id uuid REFERENCES public.persons(id), actor_profile_id uuid REFERENCES public.profiles(id), operation text NOT NULL, entity_type text NOT NULL, entity_public_id text, event_id text REFERENCES public.event_inbox(event_id), before_version bigint, after_version bigint, result text NOT NULL, metadata jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now());
CREATE TRIGGER trg_persons_updated_at BEFORE UPDATE ON public.persons FOR EACH ROW EXECUTE FUNCTION public.tc_set_updated_at();
CREATE TRIGGER trg_users_updated_at BEFORE UPDATE ON public.users FOR EACH ROW EXECUTE FUNCTION public.tc_set_updated_at();
CREATE TRIGGER trg_profiles_updated_at BEFORE UPDATE ON public.profiles FOR EACH ROW EXECUTE FUNCTION public.tc_set_updated_at();
CREATE TRIGGER trg_store_directory_updated_at BEFORE UPDATE ON public.store_directory FOR EACH ROW EXECUTE FUNCTION public.tc_set_updated_at();
CREATE TRIGGER trg_orders_updated_at BEFORE UPDATE ON public.orders FOR EACH ROW EXECUTE FUNCTION public.tc_set_updated_at();
CREATE TRIGGER trg_sub_orders_updated_at BEFORE UPDATE ON public.sub_orders FOR EACH ROW EXECUTE FUNCTION public.tc_set_updated_at();
CREATE TRIGGER trg_packages_updated_at BEFORE UPDATE ON public.packages FOR EACH ROW EXECUTE FUNCTION public.tc_set_updated_at();
CREATE TRIGGER trg_vehicles_updated_at BEFORE UPDATE ON public.vehicles FOR EACH ROW EXECUTE FUNCTION public.tc_set_updated_at();
CREATE TRIGGER trg_route_opportunities_updated_at BEFORE UPDATE ON public.route_opportunities FOR EACH ROW EXECUTE FUNCTION public.tc_set_updated_at();
CREATE TRIGGER trg_route_assignments_updated_at BEFORE UPDATE ON public.route_assignments FOR EACH ROW EXECUTE FUNCTION public.tc_set_updated_at();
CREATE TRIGGER trg_movements_updated_at BEFORE UPDATE ON public.movements FOR EACH ROW EXECUTE FUNCTION public.tc_set_updated_at();
CREATE OR REPLACE FUNCTION public.tc_handle_new_auth_user() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,auth,pg_temp AS $$ DECLARE v_person_id uuid; BEGIN INSERT INTO public.persons(public_id,auth_user_id,full_name,email,phone,preferred_language) VALUES(public.tc_generate_public_id('PER'),NEW.id,NULLIF(NEW.raw_user_meta_data->>'full_name',''),NEW.email,NEW.phone,COALESCE(NULLIF(NEW.raw_user_meta_data->>'preferred_language',''),'es')) RETURNING id INTO v_person_id; INSERT INTO public.users(id,person_id,display_name,photo_url) VALUES(NEW.id,v_person_id,NULLIF(NEW.raw_user_meta_data->>'full_name',''),NULLIF(NEW.raw_user_meta_data->>'avatar_url','')); RETURN NEW; END; $$;
REVOKE ALL ON FUNCTION public.tc_handle_new_auth_user() FROM PUBLIC;
CREATE TRIGGER on_auth_user_created_tc AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.tc_handle_new_auth_user();
CREATE OR REPLACE FUNCTION public.current_user_person_id() RETURNS uuid LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$ SELECT p.id FROM public.persons p WHERE p.auth_user_id=auth.uid() LIMIT 1; $$;
CREATE OR REPLACE FUNCTION public.current_user_profile_ids() RETURNS TABLE(profile_id uuid,profile_type text,territory_id text) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$ SELECT p.id,p.profile_type,p.territory_id FROM public.profiles p JOIN public.persons per ON per.id=p.person_id WHERE per.auth_user_id=auth.uid() AND p.status='active'; $$;
REVOKE ALL ON FUNCTION public.current_user_person_id() FROM PUBLIC; REVOKE ALL ON FUNCTION public.current_user_profile_ids() FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.current_user_person_id() TO authenticated; GRANT EXECUTE ON FUNCTION public.current_user_profile_ids() TO authenticated;
CREATE OR REPLACE VIEW public.public_store_profiles WITH(security_invoker=true) AS SELECT sd.store_public_id,sd.commercial_name,sd.territory_id,sd.community_label,sd.is_open,sd.rating,sd.updated_at FROM public.store_directory sd WHERE sd.is_active=true;
CREATE OR REPLACE VIEW public.my_package_tracking WITH(security_invoker=true) AS SELECT pkg.public_id AS package_public_id,pkg.state,pkg.version,pkg.updated_at AS last_update_at FROM public.packages pkg;
CREATE INDEX idx_persons_auth_user_id ON public.persons(auth_user_id); CREATE INDEX idx_profiles_person_id ON public.profiles(person_id); CREATE INDEX idx_profiles_type_status_territory ON public.profiles(profile_type,status,territory_id); CREATE INDEX idx_orders_client_profile ON public.orders(client_profile_id); CREATE INDEX idx_sub_orders_order_id ON public.sub_orders(order_id); CREATE INDEX idx_sub_orders_store_profile ON public.sub_orders(store_profile_id); CREATE INDEX idx_packages_sub_order ON public.packages(sub_order_id); CREATE INDEX idx_packages_custodian ON public.packages(current_custodian_id); CREATE INDEX idx_driver_vehicle_driver ON public.driver_vehicle_authorizations(driver_profile_id); CREATE INDEX idx_driver_vehicle_vehicle ON public.driver_vehicle_authorizations(vehicle_id); CREATE INDEX idx_route_opp_territory_state ON public.route_opportunities(territory_id,state); CREATE INDEX idx_route_assignments_driver ON public.route_assignments(driver_profile_id); CREATE INDEX idx_route_assignments_route ON public.route_assignments(route_id); CREATE INDEX idx_movements_route ON public.movements(route_id); CREATE INDEX idx_movements_assignment ON public.movements(route_assignment_id); CREATE INDEX idx_movements_from_profile ON public.movements(from_profile_id); CREATE INDEX idx_movements_to_profile ON public.movements(to_profile_id); CREATE INDEX idx_movements_state ON public.movements(state); CREATE INDEX idx_movement_packages_package ON public.movement_packages(package_id); CREATE INDEX idx_event_inbox_profile ON public.event_inbox(profile_id); CREATE INDEX idx_event_inbox_package ON public.event_inbox(package_id); CREATE INDEX idx_event_inbox_movement ON public.event_inbox(movement_id); CREATE INDEX idx_event_inbox_route ON public.event_inbox(route_id); CREATE INDEX idx_event_inbox_status_received ON public.event_inbox(processing_status,received_at); CREATE INDEX idx_custody_events_package ON public.custody_events(package_id); CREATE INDEX idx_custody_events_event ON public.custody_events(event_id); CREATE INDEX idx_sync_conflicts_status ON public.sync_conflicts(resolution_status,detected_at); CREATE INDEX idx_evidence_package ON public.evidence(package_id); CREATE INDEX idx_evidence_event ON public.evidence(source_event_id); CREATE INDEX idx_audit_entity ON public.audit_logs(entity_type,entity_public_id); CREATE INDEX idx_audit_event ON public.audit_logs(event_id);
ALTER TABLE public.persons ENABLE ROW LEVEL SECURITY; ALTER TABLE public.users ENABLE ROW LEVEL SECURITY; ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY; ALTER TABLE public.store_directory ENABLE ROW LEVEL SECURITY; ALTER TABLE public.orders ENABLE ROW LEVEL SECURITY; ALTER TABLE public.sub_orders ENABLE ROW LEVEL SECURITY; ALTER TABLE public.packages ENABLE ROW LEVEL SECURITY; ALTER TABLE public.vehicles ENABLE ROW LEVEL SECURITY; ALTER TABLE public.driver_vehicle_authorizations ENABLE ROW LEVEL SECURITY; ALTER TABLE public.route_opportunities ENABLE ROW LEVEL SECURITY; ALTER TABLE public.route_assignments ENABLE ROW LEVEL SECURITY; ALTER TABLE public.movements ENABLE ROW LEVEL SECURITY; ALTER TABLE public.movement_packages ENABLE ROW LEVEL SECURITY; ALTER TABLE public.idempotency_records ENABLE ROW LEVEL SECURITY; ALTER TABLE public.event_inbox ENABLE ROW LEVEL SECURITY; ALTER TABLE public.custody_events ENABLE ROW LEVEL SECURITY; ALTER TABLE public.sync_conflicts ENABLE ROW LEVEL SECURITY; ALTER TABLE public.evidence ENABLE ROW LEVEL SECURITY; ALTER TABLE public.audit_logs ENABLE ROW LEVEL SECURITY;
CREATE POLICY persons_self_read ON public.persons FOR SELECT TO authenticated USING(auth_user_id=auth.uid()); CREATE POLICY users_self_read ON public.users FOR SELECT TO authenticated USING(id=auth.uid()); CREATE POLICY profiles_self_read ON public.profiles FOR SELECT TO authenticated USING(person_id=public.current_user_person_id()); CREATE POLICY store_directory_public_read ON public.store_directory FOR SELECT TO anon,authenticated USING(is_active=true);
CREATE POLICY orders_client_read ON public.orders FOR SELECT TO authenticated USING(client_profile_id IN (SELECT profile_id FROM public.current_user_profile_ids() WHERE profile_type='CLI'));
CREATE POLICY sub_orders_read ON public.sub_orders FOR SELECT TO authenticated USING(order_id IN (SELECT o.id FROM public.orders o WHERE o.client_profile_id IN (SELECT profile_id FROM public.current_user_profile_ids() WHERE profile_type='CLI')) OR store_profile_id IN (SELECT profile_id FROM public.current_user_profile_ids() WHERE profile_type IN ('VEN','TIE')));
CREATE POLICY packages_read ON public.packages FOR SELECT TO authenticated USING(current_custodian_id IN (SELECT profile_id FROM public.current_user_profile_ids()) OR sub_order_id IN (SELECT so.id FROM public.sub_orders so JOIN public.orders o ON o.id=so.order_id WHERE o.client_profile_id IN (SELECT profile_id FROM public.current_user_profile_ids() WHERE profile_type='CLI') OR so.store_profile_id IN (SELECT profile_id FROM public.current_user_profile_ids() WHERE profile_type IN ('VEN','TIE'))));
CREATE POLICY vehicles_read ON public.vehicles FOR SELECT TO authenticated USING(owner_profile_id IN (SELECT profile_id FROM public.current_user_profile_ids()) OR id IN (SELECT dva.vehicle_id FROM public.driver_vehicle_authorizations dva WHERE dva.driver_profile_id IN (SELECT profile_id FROM public.current_user_profile_ids() WHERE profile_type='CON') AND dva.is_active=true AND dva.valid_from<=now() AND (dva.valid_until IS NULL OR dva.valid_until>=now())));
CREATE POLICY driver_vehicle_authorizations_read ON public.driver_vehicle_authorizations FOR SELECT TO authenticated USING(driver_profile_id IN (SELECT profile_id FROM public.current_user_profile_ids() WHERE profile_type='CON'));
CREATE POLICY route_opportunities_read ON public.route_opportunities FOR SELECT TO authenticated USING((state='OPEN' AND territory_id IN (SELECT territory_id FROM public.current_user_profile_ids() WHERE profile_type IN ('CON','RSG') AND territory_id IS NOT NULL)) OR id IN (SELECT ra.route_id FROM public.route_assignments ra WHERE ra.driver_profile_id IN (SELECT profile_id FROM public.current_user_profile_ids() WHERE profile_type='CON')));
CREATE POLICY route_assignments_read ON public.route_assignments FOR SELECT TO authenticated USING(driver_profile_id IN (SELECT profile_id FROM public.current_user_profile_ids() WHERE profile_type='CON'));
CREATE POLICY movements_read ON public.movements FOR SELECT TO authenticated USING(from_profile_id IN (SELECT profile_id FROM public.current_user_profile_ids()) OR to_profile_id IN (SELECT profile_id FROM public.current_user_profile_ids()) OR route_assignment_id IN (SELECT ra.id FROM public.route_assignments ra WHERE ra.driver_profile_id IN (SELECT profile_id FROM public.current_user_profile_ids() WHERE profile_type='CON')));
CREATE POLICY movement_packages_read ON public.movement_packages FOR SELECT TO authenticated USING(movement_id IN (SELECT m.id FROM public.movements m)); CREATE POLICY event_inbox_self_read ON public.event_inbox FOR SELECT TO authenticated USING(profile_id IN (SELECT profile_id FROM public.current_user_profile_ids())); CREATE POLICY custody_events_read ON public.custody_events FOR SELECT TO authenticated USING(from_profile_id IN (SELECT profile_id FROM public.current_user_profile_ids()) OR to_profile_id IN (SELECT profile_id FROM public.current_user_profile_ids()) OR package_id IN (SELECT p.id FROM public.packages p)); CREATE POLICY sync_conflicts_self_read ON public.sync_conflicts FOR SELECT TO authenticated USING(event_id IN (SELECT ei.event_id FROM public.event_inbox ei WHERE ei.profile_id IN (SELECT profile_id FROM public.current_user_profile_ids()))); CREATE POLICY evidence_read ON public.evidence FOR SELECT TO authenticated USING(uploader_profile_id IN (SELECT profile_id FROM public.current_user_profile_ids()) OR package_id IN (SELECT p.id FROM public.packages p));
REVOKE INSERT,UPDATE,DELETE ON TABLE public.persons,public.users,public.profiles,public.store_directory,public.orders,public.sub_orders,public.packages,public.vehicles,public.driver_vehicle_authorizations,public.route_opportunities,public.route_assignments,public.movements,public.movement_packages,public.idempotency_records,public.event_inbox,public.custody_events,public.sync_conflicts,public.evidence,public.audit_logs FROM anon,authenticated;
GRANT SELECT ON TABLE public.store_directory,public.public_store_profiles TO anon,authenticated; GRANT SELECT ON TABLE public.persons,public.users,public.profiles,public.orders,public.sub_orders,public.packages,public.vehicles,public.driver_vehicle_authorizations,public.route_opportunities,public.route_assignments,public.movements,public.movement_packages,public.event_inbox,public.custody_events,public.sync_conflicts,public.evidence,public.my_package_tracking TO authenticated;
INSERT INTO storage.buckets(id,name,public) VALUES('tc-evidence','tc-evidence',false) ON CONFLICT(id) DO UPDATE SET public=excluded.public;
CREATE POLICY tc_evidence_insert_own_prefix ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='tc-evidence' AND (storage.foldername(name))[1]=auth.uid()::text);
CREATE OR REPLACE FUNCTION public.execute_checkout(p_client_profile_public_id text,p_destination_type text,p_destination_id text,p_items jsonb,p_idempotency_key text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='UNAUTHENTICATED'; END IF; RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='NOT_IMPLEMENTED'; END; $$;
CREATE OR REPLACE FUNCTION public.assign_driver_route(p_driver_profile_public_id text,p_vehicle_public_id text,p_route_public_id text,p_idempotency_key text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='UNAUTHENTICATED'; END IF; RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='NOT_IMPLEMENTED'; END; $$;
CREATE OR REPLACE FUNCTION public.process_event(p_event_envelope jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='UNAUTHENTICATED'; END IF; RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='NOT_IMPLEMENTED'; END; $$;
REVOKE ALL ON FUNCTION public.execute_checkout(text,text,text,jsonb,text) FROM PUBLIC; REVOKE ALL ON FUNCTION public.assign_driver_route(text,text,text,text) FROM PUBLIC; REVOKE ALL ON FUNCTION public.process_event(jsonb) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.execute_checkout(text,text,text,jsonb,text) TO authenticated; GRANT EXECUTE ON FUNCTION public.assign_driver_route(text,text,text,text) TO authenticated; GRANT EXECUTE ON FUNCTION public.process_event(jsonb) TO authenticated;
COMMIT;